import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { differenceInDays, formatDistanceToNow } from 'date-fns';
import * as FiIcons from 'react-icons/fi';
import SafeIcon from '../common/SafeIcon';
import UserManagement from '../utils/UserManagement';
import WordManagement from '../utils/WordManagement';

const { FiX, FiUpload, FiUser, FiUserPlus, FiUsers, FiFileText, FiTrash2, FiKey, FiSettings, FiCheckCircle, FiClock, FiActivity } = FiIcons;

const AdminPanel = ({ onClose, onWordsUpdate }) => {
  const [activeTab, setActiveTab] = useState('upload');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [newUserEmail, setNewUserEmail] = useState('');
  const [newUserType, setNewUserType] = useState('temporary');
  const [csvFile, setCsvFile] = useState(null);
  const [uploadStatus, setUploadStatus] = useState({ message: '', type: '' });

  const adminCredentials = {
    email: 'prepspire.team@gmail.com',
    password: 'Start@2025'
  };

  const handleLogin = (e) => {
    e.preventDefault();
    if (email === adminCredentials.email && password === adminCredentials.password) {
      setIsAuthenticated(true);
    } else {
      alert('Invalid credentials');
    }
  };

  const handleAddUser = (e) => {
    e.preventDefault();
    try {
      UserManagement.addUser(newUserEmail, newUserType);
      setNewUserEmail('');
      setUploadStatus({ message: 'User access granted successfully!', type: 'success' });
      setTimeout(() => setUploadStatus({ message: '', type: '' }), 3000);
    } catch (error) {
      alert(error.message);
    }
  };

  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (file && (file.type === 'text/csv' || file.name.endsWith('.csv'))) {
      setCsvFile(file);
      setUploadStatus({ message: '', type: '' });
    } else {
      alert('Please select a valid CSV file');
    }
  };

  const parseCSVLine = (text) => {
    const regex = /,(?=(?:(?:[^"]*"){2})*[^"]*$)/;
    return text.split(regex).map(val => val.trim().replace(/^"|"$/g, ''));
  };

  const processCsvFile = () => {
    if (!csvFile) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const csv = e.target.result;
        const lines = csv.split(/\r?\n/).filter(line => line.trim());
        if (lines.length < 2) throw new Error('CSV file is empty');
        
        const headers = parseCSVLine(lines[0]).map(h => h.toLowerCase());
        const newWords = lines.slice(1).map(line => {
          const values = parseCSVLine(line);
          const wordObj = {};
          headers.forEach((header, index) => {
            if (values[index]) wordObj[header] = values[index];
          });
          return wordObj;
        }).filter(w => w.correct && w.incorrect1);

        const stats = WordManagement.addWords(newWords);
        onWordsUpdate();
        setUploadStatus({ message: `Success! Added ${stats.added} words.`, type: 'success' });
        setCsvFile(null);
      } catch (error) {
        setUploadStatus({ message: `Error: ${error.message}`, type: 'error' });
      }
    };
    reader.readAsText(csvFile);
  };

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center z-50 p-4" onClick={onClose}>
      <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.95, opacity: 0 }} className="bg-white rounded-[2.5rem] w-full max-w-4xl max-h-[90vh] overflow-hidden shadow-2xl flex flex-col" onClick={(e) => e.stopPropagation()}>
        <div className="flex justify-between items-center p-6 sm:p-8 bg-slate-900 text-white flex-shrink-0">
          <div className="flex items-center space-x-4">
            <div className="p-3 bg-teal-500 rounded-2xl shadow-lg shadow-teal-500/20">
              <SafeIcon icon={FiSettings} className="text-xl" />
            </div>
            <div>
              <h2 className="text-xl sm:text-2xl font-black tracking-tight">Management Console</h2>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Administrator Access</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <SafeIcon icon={FiX} className="text-2xl" />
          </button>
        </div>

        {!isAuthenticated ? (
          <div className="p-8 sm:p-16 overflow-y-auto">
            <form onSubmit={handleLogin} className="max-w-md mx-auto space-y-6">
              <div className="text-center mb-10">
                <div className="bg-slate-100 w-20 h-20 rounded-[2rem] flex items-center justify-center mx-auto mb-6">
                  <SafeIcon icon={FiKey} className="text-4xl text-slate-800" />
                </div>
                <h3 className="text-2xl font-black text-slate-900 mb-2">Security Verification</h3>
                <p className="text-slate-500 font-medium">Enter administrative credentials.</p>
              </div>
              <div className="space-y-4">
                <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Email" className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-teal-500 outline-none text-slate-900 font-medium" required />
                <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Password" className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-teal-500 outline-none text-slate-900 font-medium" required />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg hover:shadow-xl transition-all">
                AUTHORIZE ACCESS
              </button>
            </form>
          </div>
        ) : (
          <>
            <div className="flex bg-slate-50 p-2 gap-2 flex-shrink-0">
              <button onClick={() => setActiveTab('upload')} className={`flex-1 py-4 rounded-2xl font-black transition-all ${activeTab === 'upload' ? 'bg-white text-teal-600 shadow-sm' : 'text-slate-400'}`}>WORD DATABASE</button>
              <button onClick={() => setActiveTab('users')} className={`flex-1 py-4 rounded-2xl font-black transition-all ${activeTab === 'users' ? 'bg-white text-teal-600 shadow-sm' : 'text-slate-400'}`}>USER ACCESS</button>
            </div>
            <div className="p-6 sm:p-10 overflow-y-auto flex-1 bg-white custom-scrollbar">
              {activeTab === 'upload' && (
                <div className="space-y-8">
                  <div className="grid sm:grid-cols-2 gap-6">
                    <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
                      <div className="flex items-center space-x-3 mb-3">
                        <SafeIcon icon={FiFileText} className="text-teal-600" />
                        <h4 className="font-black text-slate-900">CSV Template</h4>
                      </div>
                      <code className="block bg-slate-900 text-teal-400 p-3 rounded-xl text-xs">correct,incorrect1,incorrect2,incorrect3</code>
                    </div>
                    <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
                      <div className="flex items-center space-x-3 mb-3">
                        <SafeIcon icon={FiCheckCircle} className="text-teal-600" />
                        <h4 className="font-black text-slate-900">Live Updates</h4>
                      </div>
                      <p className="text-slate-500 text-sm">Changes are saved instantly to the local database.</p>
                    </div>
                  </div>
                  <div className="relative group">
                    <input type="file" accept=".csv" onChange={handleFileUpload} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                    <div className="border-4 border-dashed border-slate-100 rounded-[2.5rem] p-12 text-center group-hover:border-teal-500 transition-all">
                      <SafeIcon icon={FiUpload} className="text-4xl text-slate-400 mx-auto mb-4" />
                      <h5 className="text-xl font-black text-slate-900">{csvFile ? csvFile.name : 'Drop CSV file here'}</h5>
                    </div>
                  </div>
                  {csvFile && <button onClick={processCsvFile} className="w-full bg-teal-500 text-white font-black py-4 rounded-2xl">IMPORT WORD LIST</button>}
                </div>
              )}
              {activeTab === 'users' && (
                <div className="space-y-10">
                  <div className="bg-slate-900 rounded-[2rem] p-8 text-white">
                    <h3 className="text-xl font-black mb-6">Create New Access Point</h3>
                    <form onSubmit={handleAddUser} className="grid sm:grid-cols-2 gap-4">
                      <input type="email" value={newUserEmail} onChange={(e) => setNewUserEmail(e.target.value)} placeholder="Email" className="px-6 py-4 bg-white/10 border border-white/10 rounded-2xl text-white" required />
                      <select value={newUserType} onChange={(e) => setNewUserType(e.target.value)} className="px-6 py-4 bg-white/10 border border-white/10 rounded-2xl text-white appearance-none">
                        <option value="temporary" className="text-slate-900">Standard (14 Days / 50 Words)</option>
                        <option value="prepspire" className="text-slate-900">Prepspire Pro (Unlimited)</option>
                      </select>
                      <button type="submit" className="sm:col-span-2 bg-teal-500 text-white font-black py-4 rounded-2xl">GENERATE CREDENTIALS</button>
                    </form>
                  </div>
                  <div className="grid gap-3">
                    {UserManagement.getAllUsers().map((u, i) => (
                      <div key={i} className="flex items-center justify-between p-5 bg-slate-50 border border-slate-100 rounded-3xl hover:bg-white transition-all">
                        <div className="flex items-center space-x-4">
                          <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center shadow-sm">
                            <SafeIcon icon={FiUser} className="text-slate-400" />
                          </div>
                          <div>
                            <p className="font-black text-slate-900">{u.email}</p>
                            <div className="flex flex-wrap items-center gap-2 mt-1">
                              <span className={`text-[10px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md ${u.type === 'prepspire' ? 'bg-amber-100 text-amber-700' : 'bg-slate-200 text-slate-600'}`}>
                                {u.type}
                              </span>
                              <span className="text-[10px] text-slate-500 font-bold flex items-center gap-1">
                                <SafeIcon icon={FiClock} className="text-[10px]" />
                                Registered {formatDistanceToNow(new Date(u.createdAt))} ago
                              </span>
                              {u.type === 'temporary' && (
                                <span className="text-[10px] text-teal-600 font-bold flex items-center gap-1">
                                  <SafeIcon icon={FiActivity} className="text-[10px]" />
                                  {u.totalWordsAttempted || 0}/50 Words
                                </span>
                              )}
                            </div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </>
        )}
      </motion.div>
    </motion.div>
  );
};

export default AdminPanel;