import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import Header from './components/Header';
import LoginPage from './components/LoginPage';
import SpellingPractice from './components/SpellingPractice';
import AdminPanel from './components/AdminPanel';
import UserManagement from './utils/UserManagement';
import WordManagement from './utils/WordManagement';
import './App.css';

function App() {
  const [user, setUser] = useState(null);
  const [words, setWords] = useState([]);
  const [showAdmin, setShowAdmin] = useState(false);
  const [showHowToUse, setShowHowToUse] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);

  useEffect(() => {
    // Atomic Initialization
    const initApp = () => {
      WordManagement.initialize();
      const savedUser = UserManagement.getCurrentUser();
      if (savedUser) setUser(savedUser);
      setWords(WordManagement.getAllWords());
      setIsInitialized(true);
    };
    initApp();
  }, []);

  const handleLogin = (userData) => setUser(userData);
  const handleLogout = () => {
    UserManagement.logout();
    setUser(null);
  };

  const handleWordsUpdate = () => {
    setWords(WordManagement.getAllWords());
  };

  if (!isInitialized) return null;

  return (
    <Router>
      <div className="min-h-screen flex flex-col safe-area-bottom">
        <Header 
          user={user} 
          onLogout={handleLogout}
          onShowAdmin={() => setShowAdmin(true)}
          onShowHowToUse={() => setShowHowToUse(true)}
        />
        
        <main className="flex-1">
          <Routes>
            <Route path="/" element={
              user ? <SpellingPractice user={user} words={words} /> : <LoginPage onLogin={handleLogin} />
            } />
            <Route path="/practice" element={
              user ? <SpellingPractice user={user} words={words} /> : <Navigate to="/" replace />
            } />
          </Routes>
        </main>

        <AnimatePresence>
          {showAdmin && (
            <AdminPanel 
              onClose={() => setShowAdmin(false)} 
              onWordsUpdate={handleWordsUpdate} 
            />
          )}
        </AnimatePresence>

        <AnimatePresence>
          {showHowToUse && (
            <motion.div
              initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
              className="fixed inset-0 bg-slate-900/90 backdrop-blur-md z-[60] flex items-center justify-center p-4"
              onClick={() => setShowHowToUse(false)}
            >
              <motion.div
                initial={{ scale: 0.9, opacity: 0, y: 20 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 20 }}
                className="bg-white text-slate-800 rounded-[2.5rem] p-8 sm:p-12 max-w-xl w-full max-h-[90vh] overflow-y-auto shadow-2xl"
                onClick={(e) => e.stopPropagation()}
              >
                <div className="text-center mb-8">
                  <div className="bg-teal-50 w-20 h-20 rounded-[2rem] flex items-center justify-center mx-auto mb-6">
                    <span className="text-4xl">💡</span>
                  </div>
                  <h2 className="text-3xl font-black text-slate-900">How to Practice</h2>
                  <p className="text-slate-500 font-medium">Master spelling in 3 simple steps</p>
                </div>

                <div className="space-y-8">
                  <div className="flex gap-5">
                    <div className="w-10 h-10 bg-teal-500 text-white rounded-xl flex items-center justify-center font-black flex-shrink-0">1</div>
                    <div>
                      <h3 className="font-black text-lg text-slate-900">Analyze the Word</h3>
                      <p className="text-slate-600 leading-relaxed">A word will appear. Look at it carefully and decide if it's spelled correctly or not.</p>
                    </div>
                  </div>
                  <div className="flex gap-5">
                    <div className="w-10 h-10 bg-sky-500 text-white rounded-xl flex items-center justify-center font-black flex-shrink-0">2</div>
                    <div>
                      <h3 className="font-black text-lg text-slate-900">Correct Mistakes</h3>
                      <p className="text-slate-600 leading-relaxed">If you choose "Incorrect", you must provide the right spelling. You get two tries!</p>
                    </div>
                  </div>
                  <div className="flex gap-5">
                    <div className="w-10 h-10 bg-indigo-500 text-white rounded-xl flex items-center justify-center font-black flex-shrink-0">3</div>
                    <div>
                      <h3 className="font-black text-lg text-slate-900">Track Proficiency</h3>
                      <p className="text-slate-600 leading-relaxed">Finish the session to see your estimated IELTS Band and TOEFL scores based on accuracy.</p>
                    </div>
                  </div>
                </div>

                <button 
                  onClick={() => setShowHowToUse(false)}
                  className="w-full mt-10 bg-slate-900 text-white py-5 rounded-2xl font-black text-lg hover:bg-teal-600 transition-all shadow-xl"
                >
                  START PRACTICING
                </button>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </Router>
  );
}

export default App;