import { useState, useCallback, useMemo } from 'react';
import ScoreCalculator from '../utils/ScoreCalculator';

export const useSpellingSession = (user, words) => {
  const [sessionState, setSessionState] = useState({
    isActive: false,
    currentIndex: 0,
    sessionWords: [],
    results: [],
    isComplete: false,
    finalScore: null
  });

  const getSessionLength = useCallback(() => {
    switch (user?.type) {
      case 'guest': return 5;
      case 'prepspire': return 20;
      default: return 10;
    }
  }, [user]);

  const startSession = useCallback(() => {
    if (!words || words.length === 0) return;
    
    const length = getSessionLength();
    const isGuest = user?.type === 'guest';
    
    // GUEST RESTRICTION: Always use the exact same first 5 words
    const pool = isGuest ? words.slice(0, length) : [...words].sort(() => Math.random() - 0.5);
    
    const selectedWords = [];
    for (let i = 0; i < length; i++) {
      const wordData = pool[i % pool.length];
      
      // GUEST RESTRICTION: Fixed pattern of correct/incorrect
      const isCorrect = isGuest ? (i % 2 === 0) : (Math.random() > 0.5);
      
      const incorrectKeys = Object.keys(wordData).filter(k => k.startsWith('incorrect'));
      // Fixed variant for guests
      const variantIdx = isGuest ? (i % incorrectKeys.length) : Math.floor(Math.random() * incorrectKeys.length);
      const randomIncorrect = wordData[incorrectKeys[variantIdx]];

      selectedWords.push({
        word: isCorrect ? wordData.correct : randomIncorrect,
        isCorrect,
        correctSpelling: wordData.correct
      });
    }

    setSessionState({
      isActive: true,
      currentIndex: 0,
      sessionWords: selectedWords,
      results: [],
      isComplete: false,
      finalScore: null
    });
  }, [words, getSessionLength, user]);

  const recordResult = useCallback((userGotRight, userCorrection = null) => {
    setSessionState(prev => {
      const currentWord = prev.sessionWords[prev.currentIndex];
      const newResult = {
        word: currentWord.word,
        wasCorrect: currentWord.isCorrect,
        userGotRight,
        userCorrection,
        correctSpelling: currentWord.correctSpelling
      };

      const updatedResults = [...prev.results, newResult];
      const nextIndex = prev.currentIndex + 1;
      const isSessionFinished = nextIndex >= prev.sessionWords.length;

      return {
        ...prev,
        results: updatedResults,
        currentIndex: isSessionFinished ? prev.currentIndex : nextIndex,
        isComplete: isSessionFinished,
        finalScore: isSessionFinished ? ScoreCalculator.calculateScore(updatedResults) : null
      };
    });
  }, []);

  const currentWord = useMemo(() => {
    if (!sessionState.isActive || sessionState.isComplete) return null;
    return sessionState.sessionWords[sessionState.currentIndex] || null;
  }, [sessionState.isActive, sessionState.isComplete, sessionState.sessionWords, sessionState.currentIndex]);

  return {
    ...sessionState,
    words: sessionState.sessionWords,
    currentWord,
    startSession,
    recordResult
  };
};