import { defaultWords } from '../data/defaultWords';

class WordManagement {
  static STORAGE_KEY = 'prepspire_word_database';

  /**
   * Initializes the database with default words if empty
   */
  static initialize() {
    const existing = localStorage.getItem(this.STORAGE_KEY);
    if (!existing) {
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(defaultWords));
    }
  }

  /**
   * Gets all words (defaults + uploaded)
   */
  static getAllWords() {
    this.initialize();
    const words = localStorage.getItem(this.STORAGE_KEY);
    return words ? JSON.parse(words) : defaultWords;
  }

  /**
   * Adds new words to the existing database and ensures no duplicates
   */
  static addWords(newWords) {
    const currentWords = this.getAllWords();
    
    // Simple duplicate check based on the 'correct' spelling
    const existingSpellings = new Set(currentWords.map(w => w.correct.toLowerCase()));
    
    const uniqueNewWords = newWords.filter(
      word => !existingSpellings.has(word.correct.toLowerCase())
    );

    const updatedDatabase = [...currentWords, ...uniqueNewWords];
    localStorage.setItem(this.STORAGE_KEY, JSON.stringify(updatedDatabase));
    
    return {
      total: updatedDatabase.length,
      added: uniqueNewWords.length,
      skipped: newWords.length - uniqueNewWords.length
    };
  }

  /**
   * Resets the database to defaults
   */
  static resetToDefaults() {
    localStorage.setItem(this.STORAGE_KEY, JSON.stringify(defaultWords));
    return defaultWords;
  }
}

export default WordManagement;