class ScoreCalculator {
  static calculateScore(results) {
    if (results.length === 0) {
      return { percentage: 0, ieltsLevel: 'Below Band 3', toeflLevel: 'Below 30' };
    }

    const correct = results.filter(r => r.userGotRight).length;
    const percentage = Math.round((correct / results.length) * 100);
    
    return {
      percentage,
      ieltsLevel: this.getIELTSLevel(percentage),
      toeflLevel: this.getTOEFLLevel(percentage)
    };
  }

  static getIELTSLevel(percentage) {
    if (percentage >= 90) return 'Band 8-9 (Expert/Very Good)';
    if (percentage >= 80) return 'Band 7 (Good User)';
    if (percentage >= 70) return 'Band 6 (Competent User)';
    if (percentage >= 60) return 'Band 5 (Modest User)';
    if (percentage >= 50) return 'Band 4 (Limited User)';
    if (percentage >= 30) return 'Band 3 (Extremely Limited)';
    return 'Below Band 3';
  }

  static getTOEFLLevel(percentage) {
    if (percentage >= 90) return '100-120 (Advanced)';
    if (percentage >= 80) return '80-99 (Upper Intermediate)';
    if (percentage >= 70) return '60-79 (Intermediate)';
    if (percentage >= 60) return '45-59 (Lower Intermediate)';
    if (percentage >= 50) return '35-44 (Elementary)';
    if (percentage >= 30) return '30-34 (Beginner)';
    return 'Below 30';
  }
}

export default ScoreCalculator;