import { differenceInDays } from 'date-fns';

class UserManagement {
  static STORAGE_KEY = 'prepspire_users';
  static CURRENT_USER_KEY = 'prepspire_current_user';
  static GUEST_LIMIT_KEY = 'prepspire_guest_locked';
  static TEMP_WORD_LIMIT = 50;
  static EXPIRY_DAYS = 14;

  static getAllUsers() {
    const users = localStorage.getItem(this.STORAGE_KEY);
    return users ? JSON.parse(users) : [];
  }

  static saveUsers(users) {
    localStorage.setItem(this.STORAGE_KEY, JSON.stringify(users));
  }

  static isGuestLocked() {
    return localStorage.getItem(this.GUEST_LIMIT_KEY) === 'true';
  }

  static lockGuestAccess() {
    localStorage.setItem(this.GUEST_LIMIT_KEY, 'true');
  }

  static getCurrentUser() {
    const userStr = localStorage.getItem(this.CURRENT_USER_KEY);
    if (userStr) {
      const userData = JSON.parse(userStr);
      const users = this.getAllUsers();
      const dbUser = users.find(u => u.email === userData.email);
      
      if (!dbUser && userData.type !== 'guest') {
        this.logout();
        return null;
      }

      const activeUser = dbUser || userData;

      // Check Expiry (14 days)
      if (activeUser.type === 'temporary' && activeUser.createdAt) {
        const daysActive = differenceInDays(new Date(), new Date(activeUser.createdAt));
        if (daysActive >= this.EXPIRY_DAYS) {
          this.logout();
          return null;
        }
      }

      // Check Word Limit (50 words)
      if (activeUser.type === 'temporary' && (activeUser.totalWordsAttempted || 0) >= this.TEMP_WORD_LIMIT) {
        // We don't log them out immediately so they can see the upsell in the practice component
        return activeUser;
      }

      return activeUser;
    }
    return null;
  }

  static setCurrentUser(user) {
    localStorage.setItem(this.CURRENT_USER_KEY, JSON.stringify(user));
  }

  static register(email) {
    const users = this.getAllUsers();
    const existingUser = users.find(u => u.email === email);
    if (existingUser) {
      throw new Error('User already exists');
    }
    const newUser = {
      email,
      type: 'temporary',
      createdAt: new Date().toISOString(),
      totalWordsAttempted: 0,
      lastActive: new Date().toISOString()
    };
    users.push(newUser);
    this.saveUsers(users);
    this.setCurrentUser(newUser);
    return newUser;
  }

  static login(email) {
    const users = this.getAllUsers();
    const user = users.find(u => u.email === email);
    if (user) {
      if (user.type === 'temporary') {
        const daysActive = differenceInDays(new Date(), new Date(user.createdAt));
        if (daysActive >= this.EXPIRY_DAYS) {
          throw new Error('Your 14-day temporary access has expired. Please subscribe to Prepspire.com.');
        }
      }
      user.lastActive = new Date().toISOString();
      this.saveUsers(users);
      this.setCurrentUser(user);
      return user;
    }
    return null;
  }

  static incrementWordCount(email) {
    const users = this.getAllUsers();
    const userIndex = users.findIndex(u => u.email === email);
    if (userIndex !== -1) {
      users[userIndex].totalWordsAttempted = (users[userIndex].totalWordsAttempted || 0) + 1;
      this.saveUsers(users);
      this.setCurrentUser(users[userIndex]);
      return users[userIndex];
    }
    return null;
  }

  static logout() {
    localStorage.removeItem(this.CURRENT_USER_KEY);
  }

  static addUser(email, type) {
    const users = this.getAllUsers();
    const existingUser = users.find(u => u.email === email);
    if (existingUser) {
      throw new Error('User already exists');
    }
    const newUser = {
      email,
      type,
      createdAt: new Date().toISOString(),
      totalWordsAttempted: 0
    };
    users.push(newUser);
    this.saveUsers(users);
    return newUser;
  }

  static createGuestUser() {
    if (this.isGuestLocked()) {
      throw new Error('Guest session limit reached. Please register to continue.');
    }
    const guestUser = {
      email: 'guest@prepspire.com',
      type: 'guest',
      createdAt: new Date().toISOString(),
      totalWordsAttempted: 0
    };
    this.setCurrentUser(guestUser);
    return guestUser;
  }
}

export default UserManagement;