import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import * as FiIcons from 'react-icons/fi';
import SafeIcon from '../common/SafeIcon';
import UserManagement from '../utils/UserManagement';

const { FiMail, FiUser, FiBook, FiTarget, FiAward, FiLock, FiArrowRight, FiCheckCircle } = FiIcons;

const LoginPage = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [isRegistering, setIsRegistering] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [guestLocked, setGuestLocked] = useState(false);
  const [showRegSuccess, setShowRegSuccess] = useState(false);
  const [registeredUser, setRegisteredUser] = useState(null);

  useEffect(() => {
    setGuestLocked(UserManagement.isGuestLocked());
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      if (isRegistering) {
        const user = UserManagement.register(email);
        setRegisteredUser(user);
        setShowRegSuccess(true);
      } else {
        const user = UserManagement.login(email);
        if (!user) {
          setError('User not found. Please register first.');
          setLoading(false);
          return;
        }
        onLogin(user);
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleGuestAccess = () => {
    try {
      const guestUser = UserManagement.createGuestUser();
      onLogin(guestUser);
    } catch (err) {
      setError(err.message);
      setGuestLocked(true);
    }
  };

  return (
    <div className="min-h-[calc(100vh-80px)] flex items-center justify-center px-4 py-8 sm:py-12">
      <div className="max-w-6xl w-full">
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="text-center mb-10 sm:mb-16">
          <div className="inline-block bg-white/10 backdrop-blur-xl p-4 rounded-[2rem] mb-6 border border-white/20 shadow-2xl">
            <span className="text-4xl sm:text-5xl">✍️</span>
          </div>
          <h1 className="text-5xl sm:text-7xl md:text-8xl font-black text-white mb-4 tracking-tighter"> Prepspire <span className="text-teal-300">Spelling</span> </h1>
        </motion.div>

        <div className="grid lg:grid-cols-12 gap-8 items-stretch">
          <motion.div initial={{ opacity: 0, x: -30 }} animate={{ opacity: 1, x: 0 }} className="lg:col-span-5 flex flex-col gap-6">
            <div className="bg-white/10 backdrop-blur-lg rounded-[2.5rem] p-8 sm:p-10 border border-white/20 shadow-2xl flex-1 flex flex-col justify-center">
              <h2 className="text-2xl font-black text-white mb-8">Training Modules</h2>
              <div className="space-y-8">
                {[
                  { icon: FiBook, title: "Academic Lexicon", desc: "600+ high-frequency IELTS/TOEFL words.", color: "bg-sky-500/20 text-sky-400" },
                  { icon: FiTarget, title: "Precision Drills", desc: "Identify and rectify errors in real-time.", color: "bg-teal-500/20 text-teal-400" },
                  { icon: FiAward, title: "Band Mapping", desc: "Instant score conversion to Band 1-9.", color: "bg-purple-500/20 text-purple-400" }
                ].map((feature, i) => (
                  <div key={i} className="flex items-center space-x-5 group">
                    <div className={`${feature.color} w-14 h-14 rounded-2xl flex items-center justify-center shadow-lg flex-shrink-0 group-hover:scale-110 transition-transform`}>
                      <SafeIcon icon={feature.icon} className="text-2xl" />
                    </div>
                    <div>
                      <h3 className="font-black text-white text-lg leading-none mb-1">{feature.title}</h3>
                      <p className="text-teal-50/50 text-sm">{feature.desc}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </motion.div>

          <motion.div initial={{ opacity: 0, x: 30 }} animate={{ opacity: 1, x: 0 }} className="lg:col-span-7">
            <div className="bg-white/10 backdrop-blur-xl rounded-[2.5rem] p-8 sm:p-12 border border-white/20 shadow-2xl h-full flex flex-col">
              <div className="mb-10">
                <h2 className="text-3xl font-black text-white mb-2">{isRegistering ? 'Initialize Profile' : 'Access Dashboard'}</h2>
                <p className="text-teal-100/60 font-medium">Standard access includes 14 days and 50 practice words.</p>
              </div>

              <form onSubmit={handleSubmit} className="space-y-6 flex-1">
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase tracking-widest text-teal-100/40 ml-1">Academic Email</label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-5 flex items-center pointer-events-none">
                      <SafeIcon icon={FiMail} className="text-teal-400" />
                    </div>
                    <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="w-full pl-12 pr-6 py-5 rounded-2xl bg-white/5 border-2 border-white/10 text-white font-bold focus:border-teal-400 outline-none transition-all placeholder-white/20" placeholder="student@university.edu" required />
                  </div>
                </div>

                {error && (
                  <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className="bg-red-500/20 border-2 border-red-500/20 text-red-100 px-5 py-4 rounded-2xl text-sm font-bold flex items-center gap-3">
                    <SafeIcon icon={FiLock} className="text-lg" /> {error}
                  </motion.div>
                )}

                <button type="submit" disabled={loading} className="w-full bg-white text-slate-900 font-black py-5 rounded-2xl shadow-2xl hover:bg-teal-400 hover:text-white transition-all active:scale-[0.98] disabled:opacity-50 flex items-center justify-center gap-2 group">
                  <span>{loading ? 'AUTHENTICATING...' : (isRegistering ? 'CREATE ACCOUNT' : 'SECURE SIGN IN')}</span>
                  <SafeIcon icon={FiArrowRight} className="group-hover:translate-x-1 transition-transform" />
                </button>
              </form>

              <div className="mt-8 text-center">
                <button onClick={() => setIsRegistering(!isRegistering)} className="text-teal-100/60 hover:text-white font-black text-sm uppercase tracking-widest transition-colors">
                  {isRegistering ? 'Existing student? login' : "New student? register here"}
                </button>
              </div>

              <div className="mt-10 pt-10 border-t border-white/10">
                <AnimatePresence mode="wait">
                  {guestLocked ? (
                    <motion.div key="locked" initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="bg-amber-500/10 border-2 border-amber-500/20 rounded-3xl p-6 text-center">
                      <div className="bg-amber-500 w-12 h-12 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-lg shadow-amber-500/20">
                        <SafeIcon icon={FiLock} className="text-white text-xl" />
                      </div>
                      <h4 className="text-white font-black mb-1">Guest Session Limit Reached</h4>
                    </motion.div>
                  ) : (
                    <motion.button key="unlocked" whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }} onClick={handleGuestAccess} className="w-full bg-white/5 hover:bg-white/10 text-white font-black py-5 px-6 rounded-2xl border-2 border-white/10 transition-all flex items-center justify-center space-x-3">
                      <SafeIcon icon={FiUser} className="text-teal-400 text-xl" />
                      <span>QUICK GUEST SESSION</span>
                    </motion.button>
                  )}
                </AnimatePresence>
              </div>
            </div>
          </motion.div>
        </div>
      </div>

      <AnimatePresence>
        {showRegSuccess && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-slate-900/90 backdrop-blur-md z-[100] flex items-center justify-center p-4">
            <motion.div initial={{ scale: 0.9, y: 20 }} animate={{ scale: 1, y: 0 }} className="bg-white rounded-[2.5rem] p-8 sm:p-12 max-w-md w-full text-center shadow-2xl">
              <div className="bg-teal-50 w-20 h-20 rounded-[2rem] flex items-center justify-center mx-auto mb-6">
                <SafeIcon icon={FiCheckCircle} className="text-4xl text-teal-500" />
              </div>
              <h2 className="text-3xl font-black text-slate-900 mb-4">Registration Successful!</h2>
              <div className="space-y-4 text-slate-600 font-medium mb-8">
                <p>Welcome to Prepspire! Your temporary account is now active.</p>
                <div className="bg-slate-50 p-4 rounded-2xl text-sm border border-slate-100 text-left space-y-2">
                  <div className="flex justify-between"><span>Session Limit:</span> <span className="font-bold text-slate-900">50 Words Total</span></div>
                  <div className="flex justify-between"><span>Access Validity:</span> <span className="font-bold text-slate-900">14 Days</span></div>
                </div>
                <p className="text-xs">Once your limits are reached, please subscribe to prepspire.com for permanent access.</p>
              </div>
              <button onClick={() => onLogin(registeredUser)} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg hover:bg-teal-600 transition-all">
                START LEARNING
              </button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default LoginPage;